function showHostInfo(){modal('<p class="eyebrow orange">UP TO FOUR PILOTS</p><h2>ASSEMBLE YOUR SQUAD</h2><p>Create a room, share its invite, and choose your mechs. Everyone marks ready before the host deploys. No account needed.</p><p>Keep the host’s tab open during the mission. Direct browser connections may be blocked by restrictive networks; try a different network if a connection fails.</p><button class="button primary" id="confirmHost">CREATE ONLINE ROOM ↗</button>');$('#confirmHost').onclick=()=>{$('#modal').close();hostRoom();};}
function createPeer(id){return new Peer(id,{debug:0,config:{iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]}});}
function resetNetwork(message){cancelDeployment();$('#modal').close();if(document.pointerLockElement)document.exitPointerLock();clearTimeout(joinTimeout);const old=peer;peer=null;hostConn=null;connections.clear();room='';isHost=false;connecting=false;localId='local';roster=[];old?.destroy();campaignMissionActive=false;campaign=soloCampaign;if(campaign)m=campaignMission(campaign,planetMission);if(playing||world){playing=false;world=null;$('#game').hidden=true;$('#hangar').hidden=false;sceneFlow.cut();}if(document.body.dataset.screen==='campaign'&&!campaign)menuScreen('home');updateSquad();updateMission();if(message)toast(message);}
function networkError(error){if(!peer)return;if(error.type==='peer-unavailable')resetNetwork('Room not found. Check the code and that the host is online.');else if(connecting)resetNetwork('Could not connect. Check your network and try again.');else if(error.type==='unavailable-id')resetNetwork('Room code in use. Please create a new room.');else toast('Connection warning. If your squad disconnects, create a new room.');}
async function hostRoom(){if(connecting||room)return;if(!campaign)openCampaign();if(!window.Peer){toast('Online library did not load. Reload the page to try again.');return;}connecting=true;updateSquad();const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',bytes=crypto.getRandomValues(new Uint8Array(6)),code=[...bytes].map(b=>chars[b%chars.length]).join('');try{peer=createPeer(ROOM_PROTOCOL+code);}catch{resetNetwork('This browser cannot establish an online connection.');return;}const p=peer;p.on('error',networkError);joinTimeout=setTimeout(()=>{if(connecting)resetNetwork('Signaling server unavailable. Try again or deploy solo.');},15000);p.on('open',id=>{if(peer!==p)return;clearTimeout(joinTimeout);if(room&&isHost){connecting=false;updateSquad();return;}isHost=true;room=code;localId=id;connecting=false;roster=[me()];registerRunPilot(pilot);menuScreen('campaign');updateSquad();updateMission();toast('Room '+room+' ready. Copy an invite for your squad.');});p.on('disconnected',()=>{if(peer===p&&!p.destroyed){toast('Room discovery interrupted. Reconnecting…');p.reconnect();}});p.on('connection',conn=>{let accepted=false,verifying=false,rate=0,rateAt=Date.now();conn.on('open',()=>{if(playing||deployment||roster.length>=4){safeSend(conn,{type:'reject',reason:(playing||deployment)?'Mission in progress. Join after the squad returns.':'This squad is full (4 pilots).'});setTimeout(()=>conn.close(),500);return;}const timeout=setTimeout(()=>{if(!accepted)conn.close();},8000);conn.on('data',async data=>{if(!data||typeof data!=='object')return;if(Date.now()-rateAt>1000){rate=0;rateAt=Date.now();}if(++rate>100)return;if(data.type==='hello'&&!accepted&&!verifying){verifying=true;const assigned={callsign:validCallsign(data.callsign)?data.callsign:createCallsign()};if(roster.some(member=>member.name===assigned.callsign))assigned.callsign=createCallsign();if(peer!==p||!conn.open)return;if(playing||deployment||roster.length>=4){safeSend(conn,{type:'reject',reason:'The squad is full or is already testing.'});setTimeout(()=>conn.close(),500);return;}accepted=true;clearTimeout(timeout);connections.set(conn.peer,conn);roster.push({id:conn.peer,name:assigned.callsign,build:cleanBuild(data.build),ready:false});registerRunPilot(assigned.callsign);broadcastLobby();toast('A pilot joined your squad.');return;}if(!accepted)return;const member=roster.find(x=>x.id===conn.peer);if(!member)return;if(data.type==='deployment-ready'){if(deployment?.gate?.acknowledge(conn.peer,data.ticket))tryLaunchDeployment();return;}if(data.type==='deployment-failed'&&data.ticket===deployment?.ticket){abortDeployment('A squad member could not prepare the battlefield. Try deploying again.');return;}if(data.type==='input'&&playing){setInput(world,conn.peer,data.input);}else if(data.type==='ready'&&!playing&&!deployment){member.ready=!!data.ready&&data.campaignId===campaign?.id&&data.revision===campaign?.revision&&validBuild(member.build);broadcastLobby();}else if(data.type==='refit'&&!playing&&!deployment){applyRefit(member.name,data.request);}else if(data.type==='loadout'&&!playing&&!deployment){member.build=cleanBuild(data.build);member.ready=false;broadcastLobby();}});});const gone=()=>{if(!accepted||peer!==p)return;accepted=false;connections.delete(conn.peer);roster=roster.filter(x=>x.id!==conn.peer);if(world)world.players=world.players.filter(x=>x.id!==conn.peer);if(deployment)abortDeployment('Squad link changed during loading. Ready up and deploy again.');broadcastLobby();toast('A pilot disconnected.');};conn.on('close',gone);conn.on('error',gone);});}
async function joinRoom(code){code=code.trim().toUpperCase();if(!/^[A-Z2-9]{6}$/.test(code)){toast('Enter the six-character room code.');return;}if(connecting||room)return;if(!window.Peer){toast('Online library did not load. Reload the page.');return;}connecting=true;updateSquad();try{peer=createPeer();}catch{resetNetwork('This browser does not support online connections.');return;}const p=peer;p.on('error',networkError);joinTimeout=setTimeout(()=>{if(connecting)resetNetwork('Connection timed out. Check the room code or try another network.');},18000);p.on('open',id=>{if(peer!==p)return;localId=id;hostConn=p.connect(ROOM_PROTOCOL+code,{reliable:true,serialization:'binary'});const conn=hostConn;conn.on('open',()=>safeSend(conn,{type:'hello',callsign:pilot,build:cleanBuild(build)}));conn.on('data',data=>{if(peer!==p||!data||typeof data!=='object')return;if(data.type==='reject'){resetNetwork(data.reason);return;}if(data.type==='lobby'){clearTimeout(joinTimeout);const firstJoin=!room,previousMode=m.mode,previousPractice=!!m.practice;room=code;connecting=false;roster=data.roster;m=data.mission;campaign=cleanCampaign(data.campaign);if(!playing&&(firstJoin||previousMode!==m.mode||previousPractice!==!!m.practice)){campaignView.focusLanding(campaign);menuScreen(m.mode==='operation'&&!m.practice?'campaign':'home');}receivedAt=performance.now();updateSquad();updateMission();if($('#modal').open&&$('#joinCode'))$('#modal').close();}if(data.type==='start'&&typeof data.ticket==='string'){world=data.world;m=world.mission;receivedAt=performance.now();startView(data.ticket);}if(data.type==='combat-live')enterCombat(data.ticket);if(data.type==='state'&&playing){world={...data.world,mission:world.mission};receivedAt=performance.now();if(world.status!=='playing')finish();}if(data.type==='return'){returnToHangar(false);m=data.mission;roster=data.roster;campaign=cleanCampaign(data.campaign);campaignView.focusLanding(campaign);menuScreen(campaign?'campaign':'home');updateSquad();updateMission();toast('Squad returned to campaign command.');}});conn.on('close',()=>{if(peer===p)resetNetwork('Host disconnected. Your saved mechs are safe; create or join another room.');});conn.on('error',()=>{if(peer===p)resetNetwork('Squad connection lost. Try another network or room.');});});}
function showJoin(code=''){modal(`<p class="eyebrow orange">LINK UP</p><h2>JOIN YOUR SQUAD</h2><p>Enter your host’s six-character room code. Join the host’s campaign board, choose your mech and special, then mark ready. Everyone deploys to the same battlefield.</p><label class="small-label" for="joinCode">ROOM CODE</label><input class="join-code" id="joinCode" maxlength="6" autocomplete="off" spellcheck="false" value="${escape(code)}" placeholder="ABC234"><button class="button primary full" id="confirmJoin">CONNECT TO SQUAD ↗</button>`);$('#joinCode').focus();$('#confirmJoin').onclick=()=>{joinRoom($('#joinCode').value);};$('#joinCode').onkeydown=e=>{if(e.key==='Enter')$('#confirmJoin').click();};}
async function copyRoom(){if(!room)return;const link=new URL(location.href);link.search='';link.searchParams.set('room',room);link.hash='';try{await navigator.clipboard.writeText(link.href);toast('Invite copied. Room code: '+room);}catch{modal(`<h2>INVITE YOUR SQUAD</h2><p>Room code: <strong>${room}</strong></p><input aria-label="Room invite URL" value="${escape(link.href)}" readonly id="inviteUrl"><p>Select and copy this invite link.</p>`);$('#inviteUrl').select();}}
$('#host').onclick=hostRoom;$('#join').onclick=()=>showJoin();$('#copyRoom').onclick=copyRoom;$('#leave').onclick=()=>resetNetwork('Left the squad.');$('#reroll').onclick=()=>{if(room&&!isHost)return;m=testPlatform();if(room){roster.forEach(p=>p.ready=false);broadcastLobby();}updateMission();toast('New operation generated: '+m.name);};
$('#deploy').onclick=async()=>{if(playing||deployment)return;if(m.campaign&&campaign?.runState!=='active')return;if(connecting||!validBuild(build)||(room&&isHost&&!roster.length))return;if(!initBattle($('#battle'))){toast(graphicsError());return;}initAudio();if(!room){localId='local';if(campaign&&m.mode==='operation'&&!m.practice)m=campaignMission(campaign,planetMission);world=newWorld(m,[me()]);startView();return;}const p=localPlayer();if(!p)return;if(isHost){if(roster.every(p=>p.ready&&validBuild(p.build))){if(campaign&&m.mode==='operation'&&!m.practice)m=campaignMission(campaign,planetMission);world=newWorld(m,roster);startView();}else{p.ready=true;broadcastLobby();}}else safeSend(hostConn,{type:'ready',ready:!p.ready,campaignId:campaign?.id,revision:campaign?.revision});};
function cancelDeployment(){
 if(deployment)clearTimeout(deployment.timeout);deployment=null;sceneFlow.cancel();$('#game').removeAttribute('data-arrival');$('#game').inert=false;$('#hangar').inert=false;
}
function abortDeployment(message='Deployment cancelled.'){
 if(!deployment)return;
 if(room&&!isHost){safeSend(hostConn,{type:'deployment-failed',ticket:deployment.ticket});resetNetwork(message);return;}
 returnToHangar();toast(message);
}
function enterCombat(ticket){
 if(!deployment||deployment.ticket!==ticket||!deployment.localReady||!world)return;
 clearTimeout(deployment.timeout);deployment=null;sceneFlow.launch();playTransitionSound('engage');$('#game').removeAttribute('data-arrival');$('#game').inert=false;$('#hangar').inert=false;
 campaignMissionActive=!!world.mission.campaign;clearInputs();lastTick=receivedAt=performance.now();lastSnapshot=0;playing=true;$('#battle').focus({preventScroll:true});
 if(matchMedia('(pointer:fine)').matches)mouseLook.capture();
}
function tryLaunchDeployment(){
 if(!deployment?.gate?.complete)return;
 const ticket=deployment.ticket;if(room)broadcast({type:'combat-live',ticket});enterCombat(ticket);
}
async function startView(ticket=crypto.randomUUID()){
 cancelDeployment();playing=false;campaignMissionActive=false;endShown=false;
 const token=sceneFlow.begin(world.mission,world.players.length);
 const pending=deployment={ticket,token,startedAt:performance.now(),prepared:false,insertionAt:null,localReady:false,gate:isHost||!room?createDeploymentGate(ticket,world.players.map(p=>p.id)):null};
 pending.timeout=setTimeout(()=>{if(deployment===pending)abortDeployment('Deployment timed out. The squad returned safely; ready up to retry.');},30000);
 if(isHost)broadcast({type:'start',ticket,world:snapshot(world)});
 if(document.pointerLockElement)document.exitPointerLock();$('#modal').close();clearInputs();resetView();view.yaw=world.mission.heading;resetBattle();resetSound();updateBoostSound(0);updatePreviewSound(previewBuild(),performance.now()/1000,false);
 $('#hangar').hidden=true;$('#hangar').inert=true;$('#game').hidden=false;$('#game').inert=true;$('#game').dataset.arrival='true';thrusterPreview=false;
 $('#gameOperation').textContent=world.mission.name;$('#exitGame').textContent=world.mission.campaign||world.mission.raid?'CAMPAIGN':'WORKSHOP';$('#game').classList.toggle('sandbox',['sandbox','trial'].includes(world.mission.mode));$('#levelMapPanel').hidden=true;
 $('.deployment-cancel').focus({preventScroll:true});
 const current=()=>deployment===pending&&sceneFlow.current(token);
 try{
  const ready=await prepareBattle($('#battle'),world,localId,{stage:(index,detail)=>{if(current())sceneFlow.stage(index,detail);},current});
  if(!ready||!current())return;
  pending.prepared=true;
 }catch(error){if(current()){console.error(error);abortDeployment(error.message||'Battlefield preparation failed. Try deploying again.');}}
}
function updateInsertion(t){
 const pending=deployment;if(!pending||!pending.prepared)return;
 if(pending.insertionAt===null){
  if(t-pending.startedAt<MIN_LOADING_SECONDS*1000)return;
  pending.insertionAt=t;playTransitionSound('insert');
 }
 const intro=deploymentIntro((t-pending.insertionAt)/1000,impactMode()==='reduced');
 if(!pending.localReady&&!intro.complete)sceneFlow.intro(intro.phase);
 drawBattle3D($('#battle'),world,localId,t/1000,{insertion:intro.progress,deployment:true});
 if(intro.complete&&!pending.localReady){
  clearInputs();pending.localReady=true;sceneFlow.wait();
  if(pending.gate){pending.gate.acknowledge(localId,pending.ticket);tryLaunchDeployment();}
  else safeSend(hostConn,{type:'deployment-ready',ticket:pending.ticket});
 }
}
$('.deployment-cancel').onclick=()=>abortDeployment();
window.addEventListener('keydown',event=>{if(!deployment)return;if(event.code==='Escape'){event.preventDefault();abortDeployment();}});

function returnToHangar(send=true){cancelDeployment();sceneFlow.cut();if(document.pointerLockElement)document.exitPointerLock();if(campaignMissionActive)settleCampaign(world?.status==='won'?'victory':world?.status==='lost'?'defeat':'withdrawal');campaignMissionActive=false;playing=false;world=null;clearInputs();$('#game').hidden=true;$('#hangar').hidden=false;menuScreen(campaign?'campaign':room?'home':'garage');$('#modal').close();if(isHost||!room){roster.forEach(p=>p.ready=false);}if(isHost&&send)broadcast({type:'return',mission:m,roster,campaign});updateMission();updateSquad();}
function finish(){if(endShown||!world)return;endShown=true;const won=world.status==='won';settleCampaign(won?'victory':'defeat');if(world.mission.mode==='trial'){modal(`<p class="eyebrow orange">COMBAT TRIAL</p><h2>${won?'HOSTILE NEUTRALIZED.':'MECH DISABLED.'}</h2><p>${won?'The AI mech is down. Try another loadout or run the trial again.':'Boost through its firing line, close in between bursts, or equip a shield or repair system.'}</p><div class="end-stats"><div><b>${world.kills} / 1</b><span>HOSTILE DEFEATED</span></div><div><b>${Math.floor(world.time)}s</b><span>COMBAT TIME</span></div></div>${isHost||!room?'<div class="dialog-actions"><button class="button primary" id="retryTrial">FIGHT AGAIN</button><button class="button secondary" id="trialWorkshop">WORKSHOP</button></div>':'<p>Waiting for the host to restart or return.</p><button class="button secondary" id="leaveResult">LEAVE SQUAD</button>'}`);if($('#retryTrial'))$('#retryTrial').onclick=()=>{world=newWorld(m,room?roster:[me()]);startView();};if($('#trialWorkshop'))$('#trialWorkshop').onclick=()=>{returnToHangar();menuScreen('garage');};if($('#leaveResult'))$('#leaveResult').onclick=()=>resetNetwork();return;}if(world.sortie){modal(debriefMarkup(sortieReport(world,won?'victory':'defeat'))+(isHost||!room?'<button class="button primary" id="returnHangar">RETURN TO CAMPAIGN ↗</button>':'<p>Waiting for the host to return the squad.</p><button class="button secondary" id="leaveResult">LEAVE SQUAD</button>'));if($('#returnHangar'))$('#returnHangar').onclick=()=>returnToHangar();if($('#leaveResult'))$('#leaveResult').onclick=()=>resetNetwork();return;}modal(`<p class="eyebrow orange">OPERATION ${escape(world.mission.name)}</p><h2>${won?'EXTRACTION COMPLETE.':'SQUAD LOST. REGROUP.'}</h2><p>${won?'Reactor destroyed. Squad extracted. Cinderfall is complete.':'Your loadouts are safe. Try cover, a repair system, or a different squad composition.'}</p><div class="end-stats"><div><b>${world.kills}</b><span>HOSTILES CLEARED</span></div><div><b>${world.cleared}/${world.mission.zones.length}</b><span>OBJECTIVES COMPLETE</span></div><div><b>${Math.floor(world.time/60)}:${String(Math.floor(world.time%60)).padStart(2,'0')}</b><span>MISSION TIME</span></div></div>${isHost||!room?'<button class="button primary" id="returnHangar">RETURN TO CAMPAIGN ↗</button>':'<p>Waiting for the host to return the squad to campaign command.</p><button class="button secondary" id="leaveResult">LEAVE SQUAD</button>'}`);if($('#returnHangar'))$('#returnHangar').onclick=()=>returnToHangar();if($('#leaveResult'))$('#leaveResult').onclick=()=>{$('#modal').close();resetNetwork();};}
$('#exitGame').onclick=()=>{if(world?.mission.mode==='sandbox'&&!room){returnToHangar();menuScreen('garage');return;}modal(`<h2>RETURN TO CAMPAIGN?</h2><p>${isHost?'The whole squad will withdraw to campaign command.':room?'You will leave the squad. The other pilots can continue.':'Withdraw to the campaign board. Your mechs and campaign progress are saved.'}</p><div class="dialog-actions"><button id="confirmExit" class="button primary">RETURN TO CAMPAIGN</button><button id="stay" class="button secondary">KEEP PLAYING</button></div>`);$('#stay').onclick=()=>$('#modal').close();$('#confirmExit').onclick=()=>{if(room&&!isHost){$('#modal').close();resetNetwork();}else{returnToHangar();}};};
$('#saveMech').onclick=()=>{if(!validBuild(build))return;const index=saved.findIndex(b=>buildKey(b)===buildKey(build));if(index>=0)saved[index]=cleanBuild(build);else if(saved.length<12)saved.push(cleanBuild(build));else{toast('12 save slots used. Delete a mech in Saved Mechs first.');return;}if(write('iw-builds',saved))toast(build.name+' saved to this browser.');};
function downloadBuilds(){const blob=new Blob([JSON.stringify({game:'IRONWAKE',version:6,mechs:saved.length?saved:[cleanBuild(build)]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ironwake-mechs.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showBuilds(){modal(`<p class="eyebrow orange">YOUR PERSONAL ARMORY</p><h2>SAVED MECHS <span class="muted">${saved.length}/12</span></h2><p>Saved on this browser. Export a backup to take your mechs to another device. Loading a build resets your ready status.</p>${saved.length?saved.map((b,i)=>`<div class="build-card"><div><h3 style="color:${b.color}">${escape(b.name)}</h3><p>${mechStats(b).weightClass} / ${mechStats(b).weight}t / ${b.equipment.filter(Boolean).map(id=>EQUIPMENT[id].name.split(' / ').at(-1)).join(' + ')}</p></div><div><button class="button secondary" data-load="${i}">LOAD</button><button class="text-button" data-delete="${i}" aria-label="Delete ${escape(b.name)}"> × </button></div></div>`).join(''):'<p>No saved mechs yet. Configure your mech in the workshop, then choose Save Mech.</p>'}<div class="dialog-actions"><button id="exportBuilds" class="button secondary">EXPORT MECHS ↓</button><button id="importBuilds" class="button secondary">IMPORT MECHS ↑</button><input type="file" id="importFile" accept="application/json,.json" hidden></div>`);$$('[data-load]').forEach(b=>b.onclick=()=>{build=cleanBuild(saved[+b.dataset.load]);$('#mechName').textContent=build.name;buildChanged();$('#modal').close();toast('Loaded '+build.name);});$$('[data-delete]').forEach(b=>b.onclick=()=>{saved.splice(+b.dataset.delete,1);write('iw-builds',saved);showBuilds();});$('#exportBuilds').onclick=downloadBuilds;$('#importBuilds').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>100000){toast('File too large. Import an Ironwake mech backup.');return;}try{const data=JSON.parse(await file.text());if(data.game!=='IRONWAKE'||!Array.isArray(data.mechs)||!data.mechs.every(b=>b&&typeof b==='object'))throw Error();const incoming=data.mechs.slice(0,12-saved.length).map(cleanBuild);saved.push(...incoming);write('iw-builds',saved);showBuilds();toast(incoming.length+' mechs imported.');}catch{toast('Invalid file. Choose an exported Ironwake mech backup.');}};}
function showManual(){modal(`<p class="overline">FLIGHT SCHOOL</p><h2>Two hands. Your build.</h2><div class="impact-setting"><button class="button secondary" id="manualImpactMode">IMPACT EFFECTS: ${impactMode().toUpperCase()} [V]</button><p>Full adds oversized cel explosions, melee impact arcs, camera punches, armor sparks and directional incoming-hit feedback. Reduced removes camera motion, speed lines, armor flashes and cockpit cracks while keeping the damage direction, armor-hit readout and combat audio. Press V in combat to switch. Your system motion preference is respected until you choose a mode.</p></div><div class="manual-controls"><span><kbd>LEFT CLICK</kbd> Use left hand · hold</span><span><kbd>RIGHT CLICK</kbd> Use right hand · hold</span><span><kbd>W A S D</kbd> Move · automatic boost</span><span><kbd>MOUSE</kbd> Aim continuously</span><span><kbd>Q / MIDDLE MOUSE</kbd> Strafe · hold heading</span><span><kbd>SPACE</kbd> Fly · hold</span><span><kbd>E</kbd> Special</span><span><kbd>SHIFT</kbd> Dash · 3s recharge</span></div><p>Equip any gun, melee weapon, or shield in either hand. Both hands can act at once and recover independently. There is no weapon cycling or zoom. Hold the button for repeated fire or melee attacks; release to lower a shield. All thrust is unlimited. Mouse movement always aims, including without mouse capture. Hold Q or the middle mouse button to lock your movement heading while aiming freely; release to follow your aim again. At the edge of the battlefield, the uncaptured mouse keeps turning. Esc releases the cursor and pauses aim until you click the battlefield.</p><h3>Dash through the fight.</h3><p>Every mech has a damaging dash. Press Shift to dash in your movement direction, or along your aim when stationary. It deals 160 damage and staggers each enemy you pass through once, then recharges in 3 seconds. Your weapons pause during the dash. Solid terrain stops it. E uses your equipped special.</p><h3>Give each hand a job.</h3><p>Carbine and railgun reward hits on the upper quarter of enemy armor; gold damage numbers mark precision hits. Aim at the gold strip on practice targets. Rail shots also pierce and interrupt. Shotgun blasts have a tight center for mid-range hits and push back close enemies. Rockets gently track enemies near your aim when fired; sharp dodges and cover break guidance. Plasma builds three visible purple charge pips: the fourth hit causes a burst that interrupts nearby foes. Hits from teammates combine, but charges expire after 1.5 seconds without a hit. Gatling accuracy and fire rate build while held for 0.6 seconds. Flames leave a short burn, so you can ignite a group and attack with the other hand. The phaser trades damage for reliable beam tracking and repairs. Pair range with crowd control, or burst damage with sustain. No additional buttons are needed.</p><h3>Melee earns its slot.</h3><p>The laser sword deals 180 damage on contact and launches a wide 90-damage wave. A target hit by the blade does not also take wave damage. The plasma sledgehammer deals 300 on direct contact and releases a 220m radial blast that staggers targets; an aerial slam dives to the ground first. The pile lance delivers a 288-damage thrust at 200m and interrupts attacks. Shock claws cleave at 110m and restore 3 armor per connected swing, once even when several targets are hit. The scythe sweeps a 190m circle and pulls enemies 70m closer. Most weapons sustain 180–285 damage per second at their effective range. The phaser trades damage for healing; blast damage falls off away from a direct hit. Stunned enemies take normal damage.</p><p>Hold the button assigned to the Bulwark to raise it in front of you. Its plate covers 54% of the body's height and reduces covered frontal bullet hits by 80%. Your head, feet, sides, and back remain vulnerable. Releasing the button removes protection. Two shields do not multiply damage reduction. Your other hand remains usable.</p><h3>Earn in combat. Refit between missions.</h3><p>Play nine missions across three acts. Shared salvage comes from enemies and objectives. Extract to earn one personal upgrade choice, with a second for enough salvage. Install on the campaign refit screen before the next drop. Modules stack up to three times and last the run. Defeat or withdrawal ends the run; saved workshop mechs remain. Mission drills let you practice every arena without campaign rewards.</p><h3>Cinderfall · Operation 01</h3><p>Land, destroy shield relays and orbital batteries, recover six cells for the canyon crawler, break the reactor coolant nodes, defeat the warden, and extract. Walk or fly near a loose cell to carry it; approach the crawler to deliver. You can carry one cell at a time and still fight normally. A downed or disconnected pilot drops their cell. Checkpoints repair the squad. Two emergency redeploys recover a full squad wipe after seven seconds. Stay close to a downed ally for a free revive. Avoid damage for seven seconds to start slow hull repair. All surviving pilots must land on the extraction pad for six seconds once the ship arrives.</p><h3>Your test platform.</h3><p>Targets reset automatically. Try melee on the close target and wide attacks against the cluster. E uses your special; choose Repair field for healing. Click the railgun once: it charges automatically for 0.66 seconds, fires, then recovers for 0.5 seconds. Keep holding to repeat the full charge-and-recovery cycle. Releasing finishes the current charge but stops the next cycle. Dashing cancels a charge. The Dynamo cannon reloads through movement: boost, fly, or dash 500m to charge its next 280-damage shot. Its reticle ring shows charge. Standing still, aiming, falling, or pushing against a wall does not recharge it. Every equipped item adds weight. Mix five frame parts and paint each independently. Select Boosters to choose exhaust color.</p><p>Touch: left stick moves, drag to aim, hold LEFT HAND or RIGHT HAND to attack, and hold FLIGHT to rise. Keep the host tab active in co-op.</p>`);$('#manualImpactMode').onclick=()=>{toggleImpactMode();syncImpactMode();};}

$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='builds')showBuilds();else if(b.dataset.view==='manual')showManual();else $('#modal').close();});$('#controlsLink').onclick=showManual;$('#gameHelp').onclick=showManual;
