const gameKeys=['KeyW','KeyA','KeyS','KeyD','KeyQ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyE','ShiftLeft','ShiftRight','Tab','KeyU','Digit1','Digit2','Digit3'];
window.addEventListener('keydown',e=>{if(!playing||$('#modal').open)return;if(gameKeys.includes(e.code))e.preventDefault();if(!e.repeat&&sortieHud.key(e.code)){if(document.pointerLockElement)document.exitPointerLock();return;}keys[e.code]=true;syncStrafe();if(!e.repeat&&e.code==='KeyH'){showManual();return;}if(!e.repeat&&e.code==='KeyE')pressAbility=true;if(!e.repeat&&['ShiftLeft','ShiftRight'].includes(e.code))pressDash=true;if(e.code==='Tab'&&!['sandbox','trial'].includes(world?.mission.mode))$('#levelMapPanel').hidden=false;if(!e.repeat&&e.code==='KeyV')$('#impactMode').click();if(!e.repeat&&e.code==='KeyM')$('#soundToggle').click();});
