function frame(t){const homeDelta=homeTick?Math.min(.05,(t-homeTick)/1000):0;homeTick=t;try{if(deployment&&world){updateInsertion(t);}else if(playing&&world){drawBattle3D($('#battle'),world,localId,t/1000);updateSound(world,localId);if(t-hudAt>65){updateHud();updateLabels();drawRadar();if(!$('#levelMapPanel').hidden)drawMap($('#levelMap'),world.mission,world,localId);hudAt=t;}}else if(document.body.dataset.screen==='home'){updatePreviewSound(previewBuild(),t/1000,false);updateBoostSound(0);if(!homePaused)homeTime=reduced?2:homeTime+homeDelta;drawHomeBattle3D($('#mechPreview'),build,homeTime);}else if(document.body.dataset.screen==='garage'){updatePreviewSound(previewBuild(),t/1000,equipmentPreview);updateBoostSound(thrusterPreview?.8:0,build.parts.booster);drawPreview3D($('#mechPreview'),previewBuild(),reduced?0:t/1000,thrusterPreview,equipmentPreview);}else{updateBoostSound(0);updatePreviewSound(previewBuild(),t/1000,false);}}catch(e){console.error(e);if(deployment)abortDeployment('Graphics interrupted during deployment. Try again or reload.');else toast('Graphics interrupted. Return to the workshop and reload.');}requestAnimationFrame(frame);}
